    provider: 'azure', providerName: 'Azure', docsProvider: 'Microsoft Learn', slug: 'data-platforms', title: 'Azure databases and data platforms', description: 'Choose and operate Azure SQL, PostgreSQL, Cosmos DB, storage, messaging, analytics, and data-integration services.', order: 8, duration: 25,
