    provider: 'azure', providerName: 'Azure', docsProvider: 'Microsoft Learn', slug: 'serverless-events', title: 'Azure serverless and event-driven systems', description: 'Design event-driven Azure systems with Functions, Logic Apps, Event Grid, Event Hubs, Service Bus, Durable Functions, and API Management.', order: 10, duration: 24,
    learningPoints: ['How events, commands, streams, queues, and workflows represent different integration contracts.', 'How Azure Functions scaling, triggers, retries, idempotency, and Durable Functions affect behavior.', 'How to design dead-letter handling, schema evolution, observability, and replay.'],
