    provider: 'azure', providerName: 'Azure', docsProvider: 'Microsoft Learn', slug: 'resilience-disaster-recovery', title: 'Azure resilience and disaster recovery', description: 'Engineer Azure availability and recovery with zones, regions, replication, backups, failover, chaos testing, and operational runbooks.', order: 12, duration: 26,
