function capstoneProject(topic: AdvancedCloudTopic): GuidedProject {
  const providerCli = topic.provider === 'azure' ? 'Azure CLI' : topic.provider === 'aws' ? 'AWS CLI' : 'Google Cloud CLI'
  return {
    goal: `Produce a reviewable ${topic.providerName} enterprise architecture package for a secure AI-enabled document platform. Defend the provider services, governance, identity, network, data, reliability, delivery, operations, migration, and cost decisions with evidence.`,
    prerequisites: [`Completion of the ${topic.providerName} provider lessons.`, 'A Git repository for architecture evidence.', 'Comfort reading architecture diagrams, IAM policies, network flows, and infrastructure plans.'],
    setup: ['Create a new repository named cloud-architecture-capstone.', `Create a dedicated ${topic.providerName} sandbox only if you choose to validate selected resources.`, 'Set a strict budget and do not deploy production data or secrets.', 'Create the evidence files listed below before making service choices.'],
    files: [
      { path: 'requirements.md', purpose: 'Record users, workflows, scale, data classification, compliance, SLO, RTO, RPO, and budget.' },
      { path: 'architecture.md', purpose: 'Explain components, boundaries, provider services, data flows, and alternatives.' },
      { path: 'diagrams/', purpose: 'Store context, identity, network, data, deployment, and recovery diagrams.' },
      { path: 'decisions/', purpose: 'Store architecture decision records with consequences and review triggers.' },
      { path: 'threat-model.md', purpose: 'Map assets, trust boundaries, threats, preventive controls, detections, and recovery.' },
      { path: 'runbook.md', purpose: 'Document alerts, incidents, backup restoration, regional recovery, and rollback.' },
      { path: 'cost-model.md', purpose: 'Estimate fixed, variable, data-transfer, observability, support, and recovery costs.' },
      { path: 'terraform/README.md', purpose: 'Define infrastructure module boundaries, state, environments, and validation workflow.' },
    ],
    platformNotes: [`Use ${providerCli} only with your own sandbox and authenticated terminal.`, 'Prefer architecture plans and read-only validation before provisioning chargeable services.', 'Use workload identity or federation; do not create long-lived keys for the capstone.', 'Destroy disposable resources and confirm billing after any hands-on validation.'],
    dependencies: ['Git', 'A diagramming tool', 'Terraform for infrastructure planning', `${providerCli} for optional read-only or sandbox validation`],
    steps: [
      { title: 'Define requirements and failure promises', instructions: ['Write the primary workflows and actors.', 'Quantify expected traffic, data volume, latency, availability, RTO, RPO, residency, compliance, and monthly budget.', 'List assumptions that need validation.'], checkpoint: 'requirements.md contains measurable quality attributes and names an owner for every requirement.' },
      { title: 'Design the provider foundation', instructions: ['Draw the resource hierarchy and environment boundaries.', 'Define human and workload identities, privileged access, policy inheritance, logging, billing allocation, and project or account creation.', 'Record why the boundaries fit the organization.'], checkpoint: 'The foundation diagram makes ownership, policy, identity, logs, and cost boundaries visible.' },
      { title: 'Design the workload and data paths', instructions: ['Choose runtime, storage, databases, events, AI services, and integration boundaries.', 'Draw public ingress, private dependencies, service-to-service identity, encryption, and data lifecycle.', 'Compare at least one credible alternative for each major service choice.'], checkpoint: 'The diagrams trace one user request and one background job through every trust and data boundary.' },
      { title: 'Threat-model and engineer recovery', instructions: ['Identify abuse cases and provider-specific control-plane threats.', 'Map preventive, detective, and recovery controls.', 'Design zone and region failure behavior, backups, restore tests, degraded modes, and incident roles.'], checkpoint: 'The threat model and runbook connect each high-risk failure to detection, containment, recovery, and evidence.' },
      { title: 'Define delivery and infrastructure automation', instructions: ['Describe Terraform modules, environments, remote state, policy checks, and secret handling.', 'Design build, test, scan, approval, deployment, smoke-test, observability, and rollback gates.', 'Use immutable artifact identifiers and federated pipeline identity.'], checkpoint: 'terraform/README.md and the deployment diagram describe a repeatable, reviewable, keyless, and reversible release.' },
      { title: 'Model cost and conduct a design review', instructions: ['Estimate usage and cost drivers under normal and peak traffic.', 'Document commitments, autoscaling, lifecycle, egress, logging, and disaster-recovery costs.', 'Present the package to a reviewer and record challenges, changes, unresolved risks, and review triggers.'], checkpoint: 'The repository contains a defensible architecture package and a review log showing what changed after challenge.' },
    ],
    verification: ['Every requirement maps to a component, policy, operational signal, or explicit gap.', 'Diagrams show identity, network, data, deployment, and recovery boundaries.', 'At least five significant decisions include alternatives, consequences, and review triggers.', 'The threat model includes control-plane, workload, data, supply-chain, and AI-specific threats.', 'RTO and RPO are supported by a testable backup and regional recovery design.', 'The delivery path uses federated identity, immutable artifacts, validation, and rollback.', 'The cost model includes provider services, data transfer, observability, support, and recovery capacity.', 'No credentials, state files, private data, or deployed secrets are committed.'],
    nextSteps: ['Implement the lowest-risk Terraform modules in a budget-controlled sandbox.', 'Run a tabletop incident and regional-recovery exercise.', 'Repeat the architecture review with a security, data, reliability, and finance reviewer.', 'Compare the same requirements against one other cloud provider and record portability tradeoffs.'],
  }
}

export const advancedProviderCloudLessons: Lesson[] = topics.map((topic) => ({
  id: `${topic.provider}-${topic.slug}`,
  title: topic.title,
  description: topic.description,
  order: topic.order,
  duration: topic.duration,
  difficulty: 'Intermediate',
  category: 'Cloud Engineering',
}))

export const advancedProviderCloudLessonContent: Record<string, LessonContent> = Object.fromEntries(topics.map((topic) => {
  const lessonId = `${topic.provider}-${topic.slug}`
  return [lessonId, {
    learningPoints: topic.learningPoints,
    sections: [
      { heading: 'Understand the platform mechanism', paragraphs: [topic.mechanism, topic.boundaries] },
      { heading: 'Make and operate the architecture decision', paragraphs: [topic.decisions, topic.operations] },
    ],
    callouts: [
      { title: 'Architecture boundary', text: topic.learningPoints[0], tone: 'teal' },
      { title: 'Operational proof', text: topic.learningPoints[2], tone: 'gold' },
    ],
    examples: [{ title: `${topic.providerName} architecture map`, explanation: 'Trace the provider services, boundaries, controls, and operating responsibilities in one reviewable view.', kind: 'diagram', language: 'text', content: topic.example }],
    resources: topic.resources,
    deeper: topic.deeper,
    takeaway: `Expertise in ${topic.title.toLowerCase()} means you can explain the mechanism, defend the tradeoffs, operate it under failure, and show evidence that the design meets its requirements.`,
    project: topic.capstone ? capstoneProject(topic) : undefined,
    quiz: {
      question: `What best demonstrates expertise in ${topic.title.toLowerCase()}?`,
      options: [topic.learningPoints[2], 'Memorize every service name without connecting it to requirements', 'Use administrator access so permissions never block delivery', 'Assume managed services remove the need for recovery and operational testing'],
      answer: topic.learningPoints[2],
      correctFeedback: 'Correct. Subject-matter expertise is demonstrated through defensible decisions and operating evidence, not service-name recall.',
      incorrectFeedback: `Start with this expert practice: ${topic.learningPoints[2].toLowerCase()}`,
    },
  } satisfies LessonContent]
}))
